package com.example.app06.application.service; import com.example.app06.domain.entity.Course; import com.example.app06.infrastructure.repository.CourseRepository; import java.util.List; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; @Service public class CourseService { private final CourseRepository repository; public CourseService(CourseRepository repository) { this.repository=repository; } @Transactional(readOnly=true) public List<Course> list() { return repository.findAll(); } @Transactional public Course create(Course e) { return repository.save(e); } }
